package dev.eugheist.tc4modern;
import net.minecraft.client.Minecraft;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.BlockHitResult;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.Aspect;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class OuterJourneyAudit {
 static int ticks;static volatile boolean pending;static volatile int completed;static volatile String failed;static BlockPos altar;
 static void check(boolean b,String message){if(!b)failed=message;System.out.println("TC4_OUTER_JOURNEY "+(b?"PASS ":"FAIL ")+message);}
 static void enter(ServerPlayer p){var l=p.server.overworld();int centre=40000+(int)(System.currentTimeMillis()/1000%10000)*32;altar=new BlockPos(centre*16+8,100,centre*16+8);p.teleportTo(l,altar.getX()+.5,102,altar.getZ()-3,0,0);p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.getAbilities().flying=true;p.onUpdateAbilities();l.setBlockAndUpdate(altar,CrimsonContent.ALTAR.get().defaultBlockState());l.setBlockAndUpdate(altar.above(2),CrimsonContent.OBELISK.get().defaultBlockState());var tile=(CrimsonAltarEntity)l.getBlockEntity(altar);for(int i=0;i<4;i++)tile.insertEye();NodeWorldAudit.node(l,altar.above(),thaumcraft.api.nodes.NodeType.DARK);ResearchProgress.complete(p,"OCULUS");var wand=WandParts.make(WandParts.CAPS.get("thaumium"),WandParts.RODDEFS.get("silverwood"));for(var a:Aspect.getPrimalAspects())WandData.add(wand,a,100,true);var expected=wand.copy();var cost=new thaumcraft.api.aspects.AspectList();for(var a:Aspect.getPrimalAspects())cost.add(a,100);WandData.consumeCrafting(expected,cost,true,p);p.setItemInHand(InteractionHand.MAIN_HAND,wand);var context=new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(altar.getCenter(),Direction.UP,altar,false));check(((BasicWandItem)wand.getItem()).onItemUseFirst(wand,context).consumesAction()&&tile.isOpen()&&l.getBlockEntity(altar.above()) instanceof OuterPortal.Portal,"real wand opens four-eye sinister-node entrance");for(var a:Aspect.getPrimalAspects())check(WandData.get(wand,a)==WandData.get(expected,a),"exact discounted 100 vis "+a.getTag());OuterPortal.transfer(p,altar.above());check(p.level().dimension()==OuterDimension.KEY&&ResearchProgress.completed(p.getPersistentData()).contains("ENTEROUTER"),"portal enters real dimension and grants research");check(p.isOnPortalCooldown(),"dimension transfer sets original 100-tick cooldown");}
 static void back(ServerPlayer p){var source=new BlockPos(altar.getX(),53,altar.getZ());OuterPortal.transfer(p,source);check(p.level().dimension()==net.minecraft.world.level.Level.OVERWORLD&&p.distanceToSqr(altar.getX()+.5,101,altar.getZ()+.5)<8,"return portal locates original overworld entrance");p.teleportTo(p.server.getLevel(OuterDimension.KEY),408*16+16,70,400*16+16,0,0);p.getAbilities().flying=true;p.onUpdateAbilities();}
 static void arenas(ServerPlayer p){var l=p.server.getLevel(OuterDimension.KEY);for(int kind=0;kind<4;kind++){int cx=400+kind*5,cz=400;for(int x=-13;x<=13;x++)for(int z=-13;z<=13;z++){l.setBlock(new BlockPos(cx*16+16+x,51,cz*16+16+z),OuterContent.STONE.get().defaultBlockState(),2);for(int y=52;y<=61;y++)l.setBlock(new BlockPos(cx*16+16+x,y,cz*16+16+z),Blocks.AIR.defaultBlockState(),2);}var lock=new BlockPos(cx*16+16,54,cz*16+4);OuterBossRooms.create(l,lock,cx,cz,2,kind);var area=new net.minecraft.world.phys.AABB(new BlockPos(cx*16+16,53,cz*16+16)).inflate(14);check(switch(kind){case 0->l.getEntitiesOfClass(EldritchGolem.class,area).size()==1;case 1->l.getEntitiesOfClass(EldritchWarden.class,area).size()==1;case 2->l.getEntitiesOfClass(CultistPortal.class,area).size()==1;default->l.getEntitiesOfClass(Taintacle.class,area).size()==5;},"arena "+kind+" generates original boss formation");l.getEntitiesOfClass(net.minecraft.world.entity.Mob.class,area).forEach(net.minecraft.world.entity.Entity::discard);}
 var pos=new BlockPos(7200,54,7200);l.setBlockAndUpdate(pos,OuterGate.LOCK.get().defaultBlockState());l.setBlockAndUpdate(pos.east(),OuterGate.BARRIER.get().defaultBlockState());var lock=(OuterGate.Lock)l.getBlockEntity(pos);var tablet=new net.minecraft.world.item.ItemStack(OuterItems.TABLET.get());var result=OuterGate.LOCK.get().useItemOn(tablet,l.getBlockState(pos),l,pos,p,InteractionHand.MAIN_HAND,new BlockHitResult(pos.getCenter(),Direction.NORTH,pos,false));check(result==net.minecraft.world.ItemInteractionResult.CONSUME&&tablet.isEmpty()&&lock.count==0,"runed tablet activates lock and is consumed");var saved=lock.saveWithoutMetadata(l.registryAccess());var copy=new OuterGate.Lock(pos,l.getBlockState(pos));copy.loadWithComponents(saved,l.registryAccess());check(copy.count==0,"activated lock countdown survives saving");lock.count=100;OuterGate.Lock.tick(l,pos,l.getBlockState(pos),lock);check(l.isEmptyBlock(pos)&&l.isEmptyBlock(pos.east()),"completed lock removes itself and gate barriers");}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){if(!Boolean.getBoolean("tc4modern.outerJourneyAuditOnly"))return;var mc=Minecraft.getInstance();if(mc.player==null||pending)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();final int step=ticks;if(step==100||step==220||step==320){pending=true;server.execute(()->{try{var p=server.getPlayerList().getPlayer(id);if(step<200)enter(p);else if(step<250)back(p);else arenas(p);completed++;}catch(Throwable ex){failed=ex.toString();ex.printStackTrace();}finally{pending=false;}});}if(ticks==180)LiquidDeathAudit.shot(mc,"outer-journey.png");if(ticks==460){check(completed==3,"all three server stages completed before shutdown");System.out.println(failed==null?"TC4_OUTER_JOURNEY ALL PASS":"TC4_OUTER_JOURNEY FAILED "+failed);mc.stop();}}
}
